import { Logger, OnModuleDestroy, Injectable } from '@nestjs/common';
import {
  WebSocketGateway,
  OnGatewayConnection,
  OnGatewayDisconnect,
  WebSocketServer,
  OnGatewayInit,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { DowntimeTicketMessage } from './interfaces/subscribe-downtime-ticket.interface';
import { PubSubConfigService } from '@/config/pubsub/pubsub.service';

@Injectable()
@WebSocketGateway({
  cors: {
    origin: '*',
  },
})
export class DowntimeGateway
  implements
    OnGatewayInit,
    OnGatewayConnection,
    OnGatewayDisconnect,
    OnModuleDestroy
{
  @WebSocketServer()
  public server: Server;

  private readonly clients: Set<Socket> = new Set();

  private readonly logger = new Logger(DowntimeGateway.name);

  public constructor(
    private readonly pubSubConfigService: PubSubConfigService,
  ) {}

  /** ✅ Initialize the gateway */
  public afterInit(): void {
    this.logger.log('WebSocket Gateway Initialized');
  }

  /**
   * ✅ Handle new client connections
   * @param client - The client socket instance
   */
  public handleConnection(client: Socket): void {
    this.clients.add(client);
    client.emit('welcome', { message: 'Welcome to the server!' });
    this.logger.log(
      `Client connected: ${client.id} - Total Clients: ${this.clients.size}`,
    );
    // Listen for room join requests
    client.on('joinRoom', (data: { plant: string; resource: string }) => {
      this.handleJoinRoom(client, data);
    });

    // Handle unexpected errors from client
    client.on('error', (error) => this.handleClientError(client, error));
  }

  /**
   * ✅ Handle room joining
   * @param client - The client socket instance
   * @param data - Object containing plant and resource
   * @param data.plant - The plant identifier for the room
   * @param data.resource - The resource identifier for the room
   */
  private handleJoinRoom(
    client: Socket,
    data: { plant: string; resource: string },
  ): void {
    if (!data?.plant || !data?.resource) {
      this.logger.error('Invalid data received for joining room:', data);
      return;
    }

    const roomName = `${data.plant}:${data.resource}`;
    client.join(roomName);

    this.logger.log(`Client ${client.id} joined room: ${roomName}`);
    client.emit('roomJoined', { message: `Joined room ${roomName}`, roomName });
  }

  /**
   * ✅ Handle client disconnection
   * @param client - The client socket instance
   */
  public handleDisconnect(client: Socket): void {
    this.clients.delete(client);
    this.logger.log(
      `Client disconnected: ${client.id} - Remaining Clients: ${this.clients.size}`,
    );
  }

  /**
   * ✅ Broadcast messages to all connected clients
   * @param data - The message data to be broadcasted to all connected clients
   */
  public handleEmit(data: DowntimeTicketMessage): void {
    const { plant, resource } = data.data;

    if (!plant || !resource) {
      this.logger.warn('Missing plant or resource in message, skipping emit');
      return;
    }
    const roomName = `${plant}:${resource}`;
    try {
      this.server.to(roomName).emit(this.pubSubConfigService.pubSubTopic, {
        message: data,
      });
      this.logger.log(`Emitted event to room: ${roomName}`);
    } catch (error) {
      this.logger.error(error);
    }
  }

  /**
   * ✅ Handle client errors
   * @param client - The client socket instance
   * @param error - The error object containing details of the error
   */
  private handleClientError(client: Socket, error: Error): void {
    this.logger.error(`Error on client ${client.id}:`, error);
    client.disconnect(true); // Force disconnect faulty client
  }

  /** ✅ Handle server shutdown (graceful cleanup) */
  public onModuleDestroy(): void {
    this.logger.warn(
      'Shutting down WebSocket server, disconnecting all clients...',
    );
    for (const client of this.clients) client.disconnect(true);
    this.clients.clear();
  }
}

