@Injectable()
export class DowntimeService {
  // Private method to determine classification mode
  private static determineClassificationMode(
    classificationMode: string,
    modifiedBy: string,
    mode: string,
  ): string {
    if (
      classificationMode === '1' &&
      modifiedBy === 'MES_SYSTEM' &&
      mode === '2'
    ) {
      return 'manual';
    }
    if (classificationMode === '2') {
      return 'voice';
    }
    return 'null';
  }

  private readonly logger = new Logger(DowntimeService.name); // Initialize logger

  private readonly customHttpService: HttpService;

  public constructor(
    private readonly httpService: HttpService,
    private readonly urlApiConfigService: UrlApiConfigService,
    private readonly apiManagerConfigService: ApiManagerConfigService,
    private readonly daprConfigService: DaprConfigService,
  ) {
    const httpsAgent = new https.Agent({
      rejectUnauthorized: true, // Enforce SSL Certificate Verification
    });

    // Create a custom Axios instance using the custom HTTPS agent
    const axiosConfig: AxiosRequestConfig = {
      httpsAgent,
      headers: this.httpService.axiosRef.defaults
        .headers as AxiosRequestConfig['headers'], // Use axios headers type
    };

    const customAxiosInstance = axios.create(axiosConfig);

    // Initialize a new HttpService with the custom Axios instance
    this.customHttpService = new HttpService(customAxiosInstance);
  }

