  public async voicetoact(
    file: Express.Multer.File,
    voicetoactDto: VoicetoactDto,
  ): Promise<Classifications> {
    const { plant_id, ticket_num, resource_id } = voicetoactDto;
    const { voiceToActApiKey, voiceToActApiUrl } = this.daprConfigService;
    // Node Buffer -> ArrayBuffer conversion to satisfy Blob constructor typings
    const { buffer } = file;
    // Create a plain ArrayBuffer copy to avoid SharedArrayBuffer being passed to Blob
    const uint8 = new Uint8Array(buffer);
    const arrayBuffer = uint8.buffer.slice(0, uint8.byteLength);
    const audio = new Blob([arrayBuffer], { type: file.mimetype });

    const secretValue = voiceToActApiKey;
    const formData = new FormData();
    formData.append('audio', audio, 'sample_test_ntrs_classification.wav');
    formData.append('plant_id', plant_id);
    formData.append('ticket_num', ticket_num);
    formData.append('resource_id', resource_id);

    const response = await axios.post(
      `${voiceToActApiUrl}/api/api/ntrs/classification`,
      formData,
      {
        headers: {
          Authorization: `Bearer ${secretValue}`,
          'Content-Type': 'multipart/form-data',
        },
      },
    );

    return response.data as Classifications;
  }

