  public async smartDMCData(
    plant: string,
    ticketnum: string,
  ): Promise<Classifications> {
    try {
      const { mainSecretStore, apiNoeeKeySecretName, apiPasswordSecretName } =
        this.apiManagerConfigService;
      const daprClient = new DaprClient();
      const secretKey = (await daprClient.secret.get(
        mainSecretStore,
        apiNoeeKeySecretName,
      )) as SecretResponse;
      const secretPassword = (await daprClient.secret.get(
        mainSecretStore,
        apiPasswordSecretName,
      )) as SecretResponse;
      const secretKeyValue = secretKey[apiNoeeKeySecretName];
      const secretPasswordValue = secretPassword[apiPasswordSecretName];

      const requestBody = {
        where: {
          field: 'plantNtrsTicket',
          type: 'eq',
          value: `${plant}_${ticketnum}`,
        },
      };

      const config: AxiosRequestConfig = {
        auth: {
          password: secretPasswordValue,
          username: await this.apiManagerConfigService.apiNoeeUsername(),
        },
        headers: {
          'Content-Type': 'application/json',
          apiKey: secretKeyValue,
        },
      };

      const apiManager = await this.apiManagerConfigService.apiManager();
      const response = await axios.post(
        `${apiManager}/palantirfoundry/api/v2/ontologies/default/objects/NoeeCausePredicitions/search`,
        requestBody,
        config,
      );
      const responseData = response.data;

      const classifications: Array<Classification> = responseData.data.flatMap(
        (item: { [x: string]: string }) => {
          const classificationsArray: Array<Classification> = [];

          for (let index = 1; index <= 5; index += 1) {
            const level1Desc = item[`level1SuggestionDesc${index}`];
            const level1Code = item[`level1Suggestion${index}`];
            const level2Desc = item[`level2SuggestionDesc${index}`];
            const level2Code = item[`level2Suggestion${index}`];
            const level3Desc = item[`level3SuggestionDesc${index}`];
            const level3Code = item[`level3Suggestion${index}`];
            classificationsArray.push({
              level1: level1Desc || '',
              level1_code: level1Code || '',
              level2: level2Desc || '',
              level2_code: level2Code || '',
              level3: level3Desc || '',
              level3_code: level3Code || '',
              option: index,
            });
          }
          return classificationsArray;
        },
      );
      const result: Classifications = {
        classifications,
        comment: 'Smart DMC classification',
        status: true,
      };

      return result;
    } catch (error) {
      console.error('Error in postTicketData:', error.message);
      throw new Error(`Failed to post data: ${error.message}`);
    }
  }

