  public async processSplitTicket(
    splitTicketRequest: SplitTicketRequest,
  ): Promise<{ statusCode: string; statusMessage: string }> {
    const { ticketId, resourceId, plantID } = splitTicketRequest;
    const ticket = await this.ticketByID(plantID, resourceId, ticketId);
    if (!ticket || ticket.length === 0) {
      throw new NotFoundException('Ticket not found.');
    } else {
      if (ticket[0].status.toUpperCase() === 'DELT') {
        throw new HttpException(
          'This ticket could not be split because the ticket status is DELT.',
          400,
        );
      }
      this.validateTicketDates(ticket[0], splitTicketRequest);
      const apiManagerUrl = await this.apiManagerConfigService.apiManager();
      const mesUserName = await this.apiManagerConfigService.mesUserName();
      const daprClient = new DaprClient();
      const { mainSecretStore } = this.apiManagerConfigService;
      const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
      const { mesPasswordSecretName } = this.apiManagerConfigService;
      const apiMgrKeyObject = await daprClient.secret.get(
        mainSecretStore,
        apiMgrKeySecretName,
      );
      const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];
      const mesPasswordObject = await daprClient.secret.get(
        mainSecretStore,
        mesPasswordSecretName,
      );
      const mesPasswordValue = Object.values(mesPasswordObject)[0];
      const plantLinkBaseUrl = await this.getPlantLink(Number(plantID));
      const isApiManagerEnabled =
        await this.apiManagerConfigService.apiManagerEnabled();
      const writeBackUrl = isApiManagerEnabled
        ? `${apiManagerUrl}/mii/illuminator/v1`
        : `${plantLinkBaseUrl}/XMII/Illuminator`;
      try {
        this.updateProcessingInfo(ticketId, Number(plantID), new Date(), 1);
        const parameters = this.buildSplitTicketParameters(
          splitTicketRequest,
          plantID,
          mesUserName,
          mesPasswordValue,
          resourceId,
        );
        const response = await firstValueFrom(
          this.customHttpService.post(writeBackUrl, undefined, {
            headers: {
              apiKey: apiMgrKeyValue,
            },
            params: parameters,
          }),
        );
        const jsonData = response.data;
        const row = jsonData?.Rowsets?.Rowset[0]?.Row[0];
        if (!row) {
          this.updateProcessingInfo(ticketId, Number(plantID), null, 0);
          throw new HttpException('request to MII failed.', 400);
        }
        const statusCode = row.STATUS_CODE;
        const statusMessage = row.STATUS_MESSAGE;
        if (statusCode !== 'SUCCESS') {
          this.updateProcessingInfo(ticketId, Number(plantID), null, 0);
        }
        return { statusCode, statusMessage };
      } catch (error) {
        this.updateProcessingInfo(ticketId, Number(plantID), null, 0);
        AppLogger.log(JSON.stringify(error));
        throw new HttpException('request to MII failed.', 400);
      }
    }
  }

  private buildSplitTicketParameters(
    splitTicketRequest: SplitTicketRequest,
    plantID: number,
    mesUserName: string,
    mesPasswordValue: string,
    resourceId: string,
  ): SplitTicketParametersDto {
    this.logger.log('buildSplitTicketParameters');
    const parameters = new SplitTicketParametersDto(
      plantID,
      mesUserName,
      mesPasswordValue,
      resourceId,
    );

    // Define parameters that should be skipped (already handled in constructor)
    const skipParameters = new Set(['plantID', 'resourceId']);

    // Define parameters that need special handling
    const specialParameters: Record<string, string> = {
      userId: 'MESXSystem', // Always set userId to 'MESXSystem'
    };

    // Process each parameter from the split ticket request
    for (const [parameterName, parameterValue] of Object.entries(
      splitTicketRequest,
    )) {
      // Only process if not already handled in constructor
      if (!skipParameters.has(parameterName)) {
        if (parameterName in specialParameters) {
          // Apply special parameter handling
          parameters[parameterName] = specialParameters[parameterName];
        } else if (
          parameterValue === null ||
          parameterValue === undefined ||
          parameterValue === 'undefined'
        ) {
          // Handle null/undefined values - always set to empty string
          parameters[parameterName] = '';
        } else {
          // Format date values or convert to string
          parameters[parameterName] =
            parameterValue instanceof Date
              ? parameterValue.toISOString()
              : String(parameterValue);
        }
      }
    }

    return parameters;
  }

