  public validateTicketDates(
    ticket: TicketDto,
    splitTicketRequest: SplitTicketRequest,
  ): void {
    const errorMessage = `Ticket date validation failed for ticket ${ticket.ticket}. Validation conditions were not met.`;

    try {
      const ticketStart = new Date(ticket.startDate);
      const ticketEnd = ticket.endDate ? new Date(ticket.endDate) : null;

      // Convert splitTicketRequest date strings into Date objects
      const firstStart = new Date(splitTicketRequest.firstTicketStartDate);
      const firstEnd = new Date(splitTicketRequest.firstTicketEndDate);
      const secondStart = new Date(splitTicketRequest.secondTicketStartDate);
      const secondEnd = splitTicketRequest.secondTicketEndDate
        ? new Date(splitTicketRequest.secondTicketEndDate)
        : null;

      let isValidFirstTicketDates: boolean;
      let isValidSecondTicketDates: boolean;

      if (ticketEnd && secondEnd) {
        isValidFirstTicketDates =
          firstStart.getTime() === ticketStart.getTime() &&
          firstEnd <= ticketEnd &&
          firstEnd > firstStart;
        isValidSecondTicketDates =
          secondStart.getTime() === firstEnd.getTime() &&
          secondEnd.getTime() === ticketEnd.getTime() &&
          secondEnd > secondStart;
      } else {
        isValidFirstTicketDates =
          firstStart.getTime() === ticketStart.getTime() &&
          firstEnd > firstStart;
        isValidSecondTicketDates = secondStart.getTime() === firstEnd.getTime();
      }
      if (!isValidFirstTicketDates || !isValidSecondTicketDates) {
        this.logger.error(errorMessage); // Log the error
        throw new HttpException(errorMessage, 400); // Throw HttpException with status 400
      }
    } catch (error) {
      this.logger.error('Error validating ticket dates:', error);
      throw new HttpException(errorMessage, 400);
    }
  }

