    plantKey: number,
    lastTimestamp: Date,
  ): Promise<Array<CauseHierarchy>> {
    const daprClient = new DaprClient();
    try {
      // Construct query parameters
      const queryParameters = `plant=${plantKey}&lastTimeStamp=${lastTimestamp}`;
      // Make GET request WITHOUT a body
      const response = (await daprClient.invoker.invoke(
        this.apiManagerConfigService.productionApiAppId,
        `down-time-cause/changes?${queryParameters}`, // Query params in the URL
        HttpMethod.GET,
      )) as Array<CauseHierarchy>;

      return Array.isArray(response) ? response : []; // Ensure it's always an array
    } catch (error) {
      console.error('Error invoking Dapr service Production API:', error);
      return [];
    }
  }

  // We use dapr invoke method to get the plant link from the plant hry microservice
  public async getResourcesByPlant(plantKey: number): Promise<Array<string>> {
    const daprClient = new DaprClient();
    try {
      const response = (await daprClient.invoker.invoke(
        this.apiManagerConfigService.plantHryApiAppId,
        `resource/getResourcesByPlant/${plantKey}`,
        HttpMethod.GET,
      )) as Array<string>;

      return Array.isArray(response) ? response : [];
    } catch (error) {
      console.error('Error invoking Dapr service PLANT HRY:', error);
      return [];
    }
  }

  public async getResourcesByFamily(
    plant: number,
    families: Array<string>,
  ): Promise<Array<string>> {
    const daprClient = new DaprClient();
    try {
      // Create the request body
      const requestBody: ResourceFamilyRequest = { families, plant };

      const response = (await daprClient.invoker.invoke(
        this.apiManagerConfigService.productionApiAppId,
        `resource-family-assign/getResourcesByPlantAndFamily`,
        HttpMethod.POST,
        requestBody, // Pass DTO in the request body
      )) as Array<string>;

      return Array.isArray(response) ? response : []; // Ensure response is always an array
    } catch (error) {
      console.error('Error invoking Dapr service Production api:', error);
      return [];
    }
  }

  public async getDowntimeCauseChanges(
    plantKey: number,
    lastTimestamp: Date,
  ): Promise<Array<CauseHierarchyWithResource> | undefined> {
    try {
      // Fetch cause hierarchy data
      const causeHierarchy: Array<CauseHierarchy> =
        await this.getCauseHierarchy(plantKey, lastTimestamp);

      if (!causeHierarchy || causeHierarchy.length === 0) {
        return undefined;
      }

      // Fetch plant-level resource (for cases where `family` is empty)
      const plantResource = await this.getResourcesByPlant(plantKey);

      // Extract families that are NOT empty
      const familiesSet = new Set<string>();
      for (const cause of causeHierarchy) {
        if (cause.family.length > 0) {
          for (const family of cause.family) familiesSet.add(family);
        }
      }

      // Fetch resources by family (only if families exist)
      let familyResources: Array<string> = [];
      if (familiesSet.size > 0) {
        familyResources =
          (await this.getResourcesByFamily(plantKey, [...familiesSet])) ?? [];
      }

      // Convert `CauseHierarchy` → `CauseHierarchyWithResource`
      const enrichedCauseHierarchy: Array<CauseHierarchyWithResource> =
        causeHierarchy.map((cause) => {
          return new CauseHierarchyWithResource(
            cause.level1_id,
            cause.level1_description,
            cause.level2_id,
            cause.level2_description,
            cause.level3_id,
            cause.level3_description,
            cause.status,
            cause.family,
            cause.family.length > 0 ? familyResources : plantResource,
          );
        });

      return enrichedCauseHierarchy;
    } catch (error) {
      console.error('Error retrieving downtime cause changes:', error);
      return undefined;
    }
  }

  public async getAllCauseDesc(
    plantKey: string,
  ): Promise<Array<DownTimeCauseDto>> {
    const daprClient = new DaprClient();
    try {
      const response = (await daprClient.invoker.invoke(
        this.apiManagerConfigService.productionApiAppId,
        `down-time-cause/getAllCauseDesc/${plantKey}`,
        HttpMethod.GET,
      )) as Array<DownTimeCauseDto>;

      return response;
    } catch (error) {
      console.error(
        'Error invoking Dapr service Production API - getAllCauseDesc:',
        { error },
      );
      return [];
    }
  }

