  public async getTranslationsByCause(
    plant: number,
    cause: string,
  ): Promise<Array<CauseDescriptionTranslationItemDto>> {
    const daprClient = new DaprClient();
    const path = `down-time-cause/translations/${encodeURIComponent(cause)}?plant=${plant}`;
    const raw = await daprClient.invoker.invoke(
      this.apiManagerConfigService.productionApiAppId,
      path,
      HttpMethod.GET,
    );
    // Validate that raw is an array before casting
    if (Array.isArray(raw)) {
      return raw as Array<CauseDescriptionTranslationItemDto>;
    }
    return [];
  }

