      entries: Array<CauseDescriptionTranslationItemDto>;
    };
  }

  public async deleteTranslation(
    plant: number,
    cause: string,
    targetLanguage: string,
  ): Promise<void> {
    const daprClient = new DaprClient();
    const path = `down-time-cause/translations/${encodeURIComponent(cause)}?plant=${plant}&targetLanguage=${encodeURIComponent(targetLanguage)}`;
    await daprClient.invoker.invoke(
      this.apiManagerConfigService.productionApiAppId,
      path,
      HttpMethod.DELETE,
    );
  }

  public async addBulkCauseDescriptionTranslations(
    items: Array<{
      cause: string;
      plant: number;
      lang: string;
      translatedDesc: string;
      isManual?: boolean;
    }>,
  ): Promise<{ added: number; updated: number }> {
    const daprClient = new DaprClient();
    const path = `down-time-cause/translations/bulk`;
    const raw = await daprClient.invoker.invoke(
      this.apiManagerConfigService.productionApiAppId,
      path,
      HttpMethod.POST,
      { items },
    );

    if (raw && typeof raw === 'object') {
      const candidate = raw as Record<string, unknown>;
      const added = typeof candidate.added === 'number' ? candidate.added : 0;
      const updated =
        typeof candidate.updated === 'number' ? candidate.updated : 0;
      return { added, updated };
    }
    return { added: 0, updated: 0 };
  }

  public async getAllCausesTranslationsByPlant(
    plant: number,
  ): Promise<Array<CauseDescriptionTranslationItemDto>> {
    const daprClient = new DaprClient();
    try {
      const path = `down-time-cause/AllCausesTranslations?plant=${plant}`;
      const raw = await daprClient.invoker.invoke(
        this.apiManagerConfigService.productionApiAppId,
        path,
        HttpMethod.GET,
      );

      if (Array.isArray(raw)) {
        return raw as Array<CauseDescriptionTranslationItemDto>;
      }
      return [];
    } catch (error) {
      this.logger.error('Error exporting translations', error);
      throw error;
    }
  }

  public async addCauseDescriptionTranslation(payload: {
    plant: number;
    cause: string;
    targetLanguage: string;
    translatedDesc: string;
    isManual?: boolean;
  }): Promise<void> {
    const daprClient = new DaprClient();
    try {
      const path = `down-time-cause/add-description/${encodeURIComponent(payload.cause)}?plant=${payload.plant}`;
      await daprClient.invoker.invoke(
        this.apiManagerConfigService.productionApiAppId,
        path,
        HttpMethod.POST,
        {
          lang: payload.targetLanguage,
          translatedDesc: payload.translatedDesc,
          isManual: payload.isManual ?? true,
        },
      );
    } catch (error) {
      this.logger.error('Error adding cause description translation', error);
      throw error;
    }
  }

  private async getUserAttributes(
    userId: string,
  ): Promise<Record<string, string>> {
    const daprClient = new DaprClient();
    try {
      const userAttributesResponse = (await daprClient.invoker.invoke(
        this.apiManagerConfigService.umeApiAppId,
        `user-attribute-mapping/${userId}`,
        HttpMethod.GET,
      )) as Array<{ userAttributeName: string; value: string }>;

      const result: Record<string, string> = {};
      for (const item of userAttributesResponse) {
        result[item.userAttributeName] = item.value;
      }
      return result;
    } catch (error) {
      this.logger.error('Error getting user attributes:', error);
      throw error;
    }
  }

  public async getHierarchy(
    userId: string,
  ): Promise<Array<PlanHierarchy> | undefined> {
    try {
      const attributes = await this.getUserAttributes(userId);
      const hierarchy = await this.getRestrictedHierarchy(
        attributes.plant,
        attributes,
      );
      return hierarchy;
    } catch (error) {
      this.logger.error('Error getting restricted hierarchy:', error);
      throw error;
    }
  }

  private async getRestrictedHierarchy(
    plantId: string,
    attributes: Record<string, string>,
  ): Promise<Array<PlanHierarchy>> {
    const daprClient = new DaprClient();
    try {
      const response = (await daprClient.invoker.invoke(
        this.apiManagerConfigService.plantHryApiAppId,
        `plant/getRestrictedHierarchy/${plantId}`,
        HttpMethod.POST,
        attributes,
      )) as Array<PlanHierarchy>;

      return response;
    } catch (error) {
      this.logger.error('Error fetching hierarchy:', error);
      throw error;
    }
  }
}

