import {
  Controller,
  Delete,
  Get,
  Post,
  Query,
  Res,
  UploadedFile,
  UseInterceptors,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { Response } from 'express';
import { PictureUploadService } from './picture-upload.service';

@Controller('picture-upload')
export class PictureUploadController {
  constructor(private readonly pictureUploadService: PictureUploadService) {}

  @Get('blobsfolder')
  async listBlobsfolder(
    @Query('plant') plant: string,
    @Query('category') category: string,
  ) {
    return this.pictureUploadService.listBlobsFolder(plant, category);
  }

  @Post('uploadpicture')
  @UseInterceptors(FileInterceptor('myfile'))
  async uploadname(
    @UploadedFile() file: Express.Multer.File,
    @Query('newName') newName: string,
  ): Promise<string> {
    await this.pictureUploadService.uploadpicture(file, newName);
    return `File uploaded successfully as ${newName}`;
  }

  @Get('downloadpicture')
  async downloadPicture(
    @Query('fileName') fileName: string,
    @Res() res: Response,
  ) {
    try {
      const fileStream =
        await this.pictureUploadService.getFileStream(fileName);

      if (!fileStream) {
        return;
      }

      res.setHeader('Content-Disposition', `attachment; filename=${fileName}`);
      res.setHeader('Content-Type', 'application/octet-stream');

      fileStream.pipe(res);
    } catch (error) {
      console.error(`Failed to download file: ${fileName}`, error);
      // Handle error response to client
      res.status(500).send(`Failed to download file: ${fileName}`);
    }
  }

  @Get('displaypicture')
  async displayPicture(
    @Query('fileName') fileName: string,
    @Res() res: Response,
  ) {
    try {
      const fileStream =
        await this.pictureUploadService.getFileStream(fileName);

      if (!fileStream) {
        return;
      }

      // Set response headers
      res.setHeader('Content-Type', 'image/jpeg'); // Adjust content type as per your file type

      // Pipe the file stream directly to the response
      fileStream.pipe(res);
    } catch (error) {
      console.error(`Failed to display picture: ${fileName}`, error);
      // Handle error response to client
      res.status(500).send(`Failed to display picture: ${fileName}`);
    }
  }

  @Delete('deletepicture')
  async deletePicture(
    @Query('fileName') fileName: string,
    @Res() res: Response,
  ) {
    try {
      await this.pictureUploadService.deletePicture(fileName);
      res.status(200).send(`File deleted successfully: ${fileName}`);
    } catch (error) {
      console.error(`Failed to delete file: ${fileName}`, error);
      res.status(500).send(`Failed to delete file: ${fileName}`);
    }
  }
}

