import { Readable } from 'node:stream';
import { DefaultAzureCredential } from '@azure/identity';
import { BlobServiceClient, BlockBlobClient } from '@azure/storage-blob';
import { Injectable } from '@nestjs/common';
import blobConfigService from '@/config/blob-config/blob-config.service';

@Injectable()
export class PictureUploadService {
  private readonly blobServiceClient: BlobServiceClient;

  private readonly containerName: string;

  private readonly accountName: string;

  constructor(private readonly blobConfigService: blobConfigService) {
    this.containerName = this.blobConfigService.containerName;
    this.accountName = this.blobConfigService.accountName;
    const defaultAzureCredential = new DefaultAzureCredential();
    this.blobServiceClient = new BlobServiceClient(
      `https://${this.accountName}.blob.core.windows.net`,
      defaultAzureCredential,
    );
  }

  private getBlobClient(imageName: string): BlockBlobClient {
    const containerClient = this.blobServiceClient.getContainerClient(
      this.containerName,
    );
    return containerClient.getBlockBlobClient(imageName);
  }

  async listBlobsFolder(
    plant: string,
    category: string,
  ): Promise<Array<string>> {
    const containerClient = this.blobServiceClient.getContainerClient(
      this.containerName,
    );
    const blobNames: Array<string> = [];
    const prefix = `${plant}/${category}/`;

    try {
      for await (const blob of containerClient.listBlobsFlat()) {
        if (blob.name.startsWith(prefix)) {
          blobNames.push(blob.name);
        }
      }
    } catch (error) {
      console.error('Error listing blobs:', error);
      throw error;
    }

    return blobNames;
  }

  async uploadpicture(
    file: Express.Multer.File,
    newName: string,
  ): Promise<void> {
    const blobName = `${newName}`;
    const blobClient = this.getBlobClient(blobName);

    try {
      await blobClient.uploadData(file.buffer);
      console.log(`File uploaded successfully: ${newName}`);
    } catch (error) {
      console.error(`Failed to upload file: ${newName}`, error);
      throw new Error(`Failed to upload file: ${newName}`);
    }
  }

  public async getFileStream(fileName: string): Promise<Readable | null> {
    if (!fileName) return null;

    const blobClient = this.getBlobClient(fileName);

    try {
      const exists = await blobClient.exists();
      if (!exists) return null;

      const downloadResponse = await blobClient.download();

      if (!downloadResponse.readableStreamBody) {
        console.warn(
          `Readable stream is empty or undefined for file: ${fileName}`,
        );
        return null;
      }

      return downloadResponse.readableStreamBody as unknown as Readable;
    } catch (error) {
      console.error(`Failed to download file: ${fileName}`, error);
      return null;
    }
  }

  async deletePicture(fileName: string): Promise<void> {
    const blobClient = this.getBlobClient(fileName);

    try {
      await blobClient.delete();
      console.log(`File deleted successfully: ${fileName}`);
    } catch (error) {
      console.error(`Failed to delete file: ${fileName}`, error);
      throw new Error(`Failed to delete file: ${fileName}`);
    }
  }
}

